INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M27-CE007', 'HDSAT-RW-M27-CE007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Insurance is a means of protection from financial loss in which, in exchange for a fee, a party agrees to compensate another party in the event of a certain loss, damage, or injury. It is a form of risk management, primarily used to protect against the risk of a contingent or uncertain loss. An entity which provides insurance is known as an insurer, insurance company, insurance carrier, or underwriter. A person or entity who buys insurance is known as a policyholder, while a person or entity covered under the policy is called an insured. The insurance transaction involves the policyholder assuming a guaranteed, known, and relatively small loss in the form of a payment to the insurer (a premium) in exchange for the insurer''s promise to compensate the insured in the event of a covered loss. The loss may or may not be financial, but it must always be reducible to financial terms. Furthermore, it usually involves something in which the insured has an insurable interest established by ownership, possession, or pre-existing relationship. The insured receives a contract, called the insurance policy, which details the conditions and circumstances under which the insurer will compensate the insured, or their designated beneficiary or assignee. The amount of money charged by the insurer to the policyholder for the coverage set forth in the insurance policy is called the premium.', 'Which quotation from the text most directly supports the claim that insurance is a form of risk management?', '[{"id": "A", "text": "It is a form of risk management, primarily used to protect against the risk of a contingent or uncertain loss."}, {"id": "B", "text": "Insurance is a means of protection from financial loss in which, in exchange for a fee, a party agrees to compensate another party."}, {"id": "C", "text": "A person or entity who buys insurance is known as a policyholder."}, {"id": "D", "text": "The insured receives a contract, called the insurance policy."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Insurance", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Insurance', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M27-CE007', 'A', ARRAY['A']::TEXT[], 'The correct quotation explicitly calls insurance risk management.', '{"B": "This sentence defines insurance and the exchange.", "C": "This sentence names the buyer.", "D": "This sentence describes the contract."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M27-CI008', 'HDSAT-RW-M27-CI008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A minimum wage is the lowest remuneration that employers can legally pay their employees—the price floor below which employees may not sell their labor. Most countries had introduced minimum wage legislation by the end of the 20th century. Because minimum wages increase the cost of labor, companies often try to avoid minimum wage laws by using gig workers, by moving labor to locations with lower or nonexistent minimum wages, or by automating job functions. Minimum wage policies can vary significantly between countries or even within a country, with different regions, sectors, or age groups having their own minimum wage rates. These variations are often influenced by the cost of living, regional economic conditions, and industry-specific factors. The movement for minimum wages was initially motivated by a desire to stop the exploitation of workers in sweatshops by employers who were thought to have unfair bargaining power over them. Over time, minimum wages came to be seen as a way to help lower-income families. Modern national laws enforcing compulsory union membership and prescribing minimum wages for members were first passed in New Zealand in 1894. Although minimum wage laws are now in effect in many jurisdictions, differences of opinion exist about the benefits and drawbacks of a minimum wage.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "A minimum wage is a legal price floor on labor that raises labor costs and remains debated."}, {"id": "B", "text": "Minimum wages are identical everywhere."}, {"id": "C", "text": "A minimum wage is a maximum price employers may pay."}, {"id": "D", "text": "Minimum wage laws do not affect labor costs."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Minimum wage", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Minimum_wage', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M27-CI008', 'A', ARRAY['A']::TEXT[], 'The passage defines minimum wage, explains its effects, and describes its history and debate.', '{"C": "The text calls it the price floor below which employees may not sell their labor.", "D": "The text says minimum wages increase the cost of labor.", "B": "The text says rates vary between countries and within them."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M27-INF008', 'HDSAT-RW-M27-INF008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A minimum wage is the lowest remuneration that employers can legally pay their employees—the price floor below which employees may not sell their labor. Most countries had introduced minimum wage legislation by the end of the 20th century. Because minimum wages increase the cost of labor, companies often try to avoid minimum wage laws by using gig workers, by moving labor to locations with lower or nonexistent minimum wages, or by automating job functions. Minimum wage policies can vary significantly between countries or even within a country, with different regions, sectors, or age groups having their own minimum wage rates. These variations are often influenced by the cost of living, regional economic conditions, and industry-specific factors. The movement for minimum wages was initially motivated by a desire to stop the exploitation of workers in sweatshops by employers who were thought to have unfair bargaining power over them. Over time, minimum wages came to be seen as a way to help lower-income families. Modern national laws enforcing compulsory union membership and prescribing minimum wages for members were first passed in New Zealand in 1894. Although minimum wage laws are now in effect in many jurisdictions, differences of opinion exist about the benefits and drawbacks of a minimum wage.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M27-INF008', 'B', ARRAY['B']::TEXT[], 'The passage lists several strategies employers use to avoid minimum wage costs.', '{"D": "The text says companies often try to avoid minimum wage laws by using gig workers, relocating, or automating.", "A": "Higher labor costs discourage additional hiring at that rate.", "C": "The text says companies respond to the cost."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M27-TS008', 'HDSAT-RW-M27-TS008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A minimum wage is the lowest remuneration that employers can legally pay their employees—the price floor below which employees may not sell their labor. Most countries had introduced minimum wage legislation by the end of the 20th century. Because minimum wages increase the cost of labor, companies often try to avoid minimum wage laws by using gig workers, by moving labor to locations with lower or nonexistent minimum wages, or by automating job functions. Minimum wage policies can vary significantly between countries or even within a country, with different regions, sectors, or age groups having their own minimum wage rates. These variations are often influenced by the cost of living, regional economic conditions, and industry-specific factors. The movement for minimum wages was initially motivated by a desire to stop the exploitation of workers in sweatshops by employers who were thought to have unfair bargaining power over them. Over time, minimum wages came to be seen as a way to help lower-income families. Modern national laws enforcing compulsory union membership and prescribing minimum wages for members were first passed in New Zealand in 1894. Although minimum wage laws are now in effect in many jurisdictions, differences of opinion exist about the benefits and drawbacks of a minimum wage.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It defines minimum wage, explains employer responses and variation, and traces its history and debate."}, {"id": "B", "text": "It argues that minimum wages should be abolished."}, {"id": "C", "text": "It profiles a single minimum-wage worker."}, {"id": "D", "text": "It compares minimum wages in every country."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Minimum wage", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Minimum_wage', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M27-TS008', 'A', ARRAY['A']::TEXT[], 'The passage moves from definition to effects and then to history.', '{"C": "No worker is profiled.", "D": "Countries are mentioned generally, not compared exhaustively.", "B": "The text reports differences of opinion without recommending abolition."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M27-CE008', 'HDSAT-RW-M27-CE008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'A minimum wage is the lowest remuneration that employers can legally pay their employees—the price floor below which employees may not sell their labor. Most countries had introduced minimum wage legislation by the end of the 20th century. Because minimum wages increase the cost of labor, companies often try to avoid minimum wage laws by using gig workers, by moving labor to locations with lower or nonexistent minimum wages, or by automating job functions. Minimum wage policies can vary significantly between countries or even within a country, with different regions, sectors, or age groups having their own minimum wage rates. These variations are often influenced by the cost of living, regional economic conditions, and industry-specific factors. The movement for minimum wages was initially motivated by a desire to stop the exploitation of workers in sweatshops by employers who were thought to have unfair bargaining power over them. Over time, minimum wages came to be seen as a way to help lower-income families. Modern national laws enforcing compulsory union membership and prescribing minimum wages for members were first passed in New Zealand in 1894. Although minimum wage laws are now in effect in many jurisdictions, differences of opinion exist about the benefits and drawbacks of a minimum wage.', 'Which quotation from the text most directly supports the claim that a minimum wage is a price floor?', '[{"id": "A", "text": "Most countries had introduced minimum wage legislation by the end of the 20th century."}, {"id": "B", "text": "A minimum wage is the lowest remuneration that employers can legally pay their employees—the price floor below which employees may not sell their labor."}, {"id": "C", "text": "The movement for minimum wages was initially motivated by a desire to stop the exploitation of workers."}, {"id": "D", "text": "Minimum wage policies can vary significantly between countries."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Minimum wage", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Minimum_wage', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M27-CE008', 'B', ARRAY['B']::TEXT[], 'The correct quotation explicitly defines the minimum wage as a price floor.', '{"A": "This sentence describes the spread of legislation.", "D": "This sentence describes variation.", "C": "This sentence describes the movement''s motivation."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M27-CI009', 'HDSAT-RW-M27-CI009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A trade union (British English) or labor/labour union (North American English), often simply referred to as a union, is an organization of workers whose purpose is to maintain or improve the conditions of their employment, such as attaining better wages and benefits, improving working conditions and safety standards, establishing complaint procedures, developing rules governing the status of employees (including rules on promotions and just-cause conditions for termination), and protecting and increasing the bargaining power of workers. Trade unions typically fund their head office and legal team functions through regularly imposed fees called union dues. The union representatives in the workforce are usually made up of workplace volunteers who are often appointed by members through internal democratic elections. The trade union, through an elected leadership and bargaining committee, bargains with the employer on behalf of its members, known as the rank and file, and negotiates labour contracts (collective bargaining agreements) with employers. Unions may organize a particular section of skilled or unskilled workers (craft unionism), a cross-section of workers from various trades (general unionism), or an attempt to organize all workers within a particular industry (industrial unionism). The agreements negotiated by a union are binding on the rank-and-file members and the employer, and in some cases on other non-member workers.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "A trade union is a worker organization that bargains collectively to improve wages, benefits, and conditions."}, {"id": "B", "text": "Trade unions avoid negotiating with employers."}, {"id": "C", "text": "A trade union is an employer association that sets prices."}, {"id": "D", "text": "Unions are funded entirely by governments."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Trade union", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Trade_union', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M27-CI009', 'A', ARRAY['A']::TEXT[], 'The passage defines trade unions, explains their funding and representation, and describes types and agreements.', '{"C": "The text defines unions as organizations of workers seeking better wages and conditions.", "B": "The text says unions bargain with employers on behalf of members.", "D": "The text says unions fund their offices through fees called union dues."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
