, '[{"id": "A", "text": "Behavioral economics is the study of the psychological factors involved in the decisions of individuals or institutions."}, {"id": "B", "text": "Behavioral economics is primarily concerned with the bounds of rationality of economic agents."}, {"id": "C", "text": "Behavioral economics began as a distinct field of study in the 1970s and 1980s."}, {"id": "D", "text": "Behavioral models typically integrate insights from psychology, neuroscience and microeconomic theory."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Behavioral economics", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Behavioral_economics', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
